package io.dndroll.domain;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;
class InitialInstabilityHealingEffectTest {
    final UUID attempt=UUID.fromString("10000000-0000-0000-0000-000000000001");
    CharacterSheet zero(){var s=CharacterSheet.empty("Target");var b=s.combat();return s.change(s.name(),new CharacterSheet.Combat(12,0,7,b.speed(),1,2,b.acMode(),b.manualAc(),b.source()),s.resources(),List.of(),s.overrides());}
    List<CharacterSheet.Condition> canonical(){return List.of(StabilizationEffect.plan(zero(),CharacterSheet.empty("Helper"),attempt,true,true,true,20).annotations().get(1));}
    CharacterSheet unstable(){var s=zero();var b=s.combat();return s.change(s.name(),new CharacterSheet.Combat(12,0,7,b.speed(),0,2,b.acMode(),b.manualAc(),b.source()),s.resources(),canonical(),s.overrides());}
    InitialInstabilityHealingEffect.Plan plan(CharacterSheet s,int n){return InitialInstabilityHealingEffect.plan(s,canonical(),true,n,true);}
    void manual(InitialInstabilityHealingEffect.Plan p,String reason){assertEquals("MANUAL_REQUIRED",p.status());assertTrue(p.reasons().contains(reason),p.reasons().toString());assertNull(p.hp());assertNull(p.healed());assertTrue(p.removed().isEmpty());}
    @Test void restoresOneRealHpResetsBothDeathCountsAndRemovesOnlyOriginalUnconscious(){var s=unstable();var p=plan(s,1);assertEquals("CANDIDATE",p.status());assertEquals(1,p.hp());assertEquals(1,p.healed());assertEquals(7,p.tempHp());assertEquals(0,p.deathSuccesses());assertEquals(0,p.deathFailures());assertEquals(canonical().stream().map(CharacterSheet.Condition::id).toList(),p.removed());assertEquals(unstable(),s);}
    @Test void capsRealHealingAtMaximumWithoutUsingTemporaryHp(){for(int n:List.of(12,13,100000)){var p=plan(unstable(),n);assertEquals("CANDIDATE",p.status());assertEquals(12,p.hp());assertEquals(12,p.healed());assertEquals(7,p.tempHp());}}
    @Test void needsAuthoritativeOriginalAndReview(){manual(InitialInstabilityHealingEffect.plan(unstable(),canonical(),false,1,true),"UNCHANGED_INITIAL_INSTABILITY_ORIGIN_REQUIRED");manual(InitialInstabilityHealingEffect.plan(unstable(),canonical(),true,1,false),"HEALING_REVIEW_REQUIRED");}
    @Test void rejectsMissingExtraAndAlteredCanonicalRecords(){var s=unstable();manual(InitialInstabilityHealingEffect.plan(s,null,true,1,true),"ORIGINAL_UNCONSCIOUS_ONLY_REQUIRED");for(var list:List.of(List.<CharacterSheet.Condition>of(),List.of(new CharacterSheet.Condition("other","昏迷","","Other source",canonical().getFirst().source(),null,null)))){manual(plan(s.change(s.name(),s.combat(),s.resources(),list,s.overrides()),1),"ORIGINAL_UNCONSCIOUS_ONLY_REQUIRED");}var extra=new ArrayList<>(canonical());extra.add(new CharacterSheet.Condition("other","昏迷","","Other source",canonical().getFirst().source(),null,null));manual(plan(s.change(s.name(),s.combat(),s.resources(),extra,s.overrides()),1),"ORIGINAL_UNCONSCIOUS_ONLY_REQUIRED");}
    @Test void rejectsNonzeroHpAndDeathCounters(){var s=unstable();var b=s.combat();for(var c:List.of(new CharacterSheet.Combat(12,1,7,b.speed(),0,0,b.acMode(),b.manualAc(),b.source()),new CharacterSheet.Combat(12,0,7,b.speed(),1,2,b.acMode(),b.manualAc(),b.source()),new CharacterSheet.Combat(12,0,7,b.speed(),0,0,b.acMode(),b.manualAc(),b.source()),new CharacterSheet.Combat(12,0,7,b.speed(),0,3,b.acMode(),b.manualAc(),b.source()))){manual(plan(s.change(s.name(),c,s.resources(),s.conditions(),s.overrides()),1),"INSTABILITY_VALUES_REQUIRED");}}
    @Test void rejectsAdjustments(){var s=unstable();manual(plan(s.change(s.name(),s.combat(),s.resources(),s.conditions(),List.of(new CharacterSheet.Override("ac",20,"test"))),1),"TARGET_ADJUSTMENTS_REQUIRE_MANUAL");}
    @Test void invalidInputsAreRejected(){assertThrows(DomainException.class,()->plan(null,1));for(int n:List.of(0,-1,100001,Integer.MAX_VALUE))assertThrows(DomainException.class,()->plan(unstable(),n));}
    @Test void planIsDeterministicAndImmutable(){var p=plan(unstable(),3);assertEquals(p,plan(unstable(),3));assertThrows(UnsupportedOperationException.class,()->p.removed().add("x"));assertThrows(UnsupportedOperationException.class,()->p.reasons().add("x"));}
}
